import { BORDER, SURFACE, TEXT, textStyle, ensureModalPanelTexture, mountForestModal } from './ForestModal';
/**
 * HelpOverlay – Steuerungsübersicht als modales Overlay.
 * Wird über den „?"-Button in der Lobby geöffnet.
 * Schließt sich automatisch bei Klick oder Tastendruck.
 */
import * as Phaser from 'phaser';
import {
  GAME_WIDTH, GAME_HEIGHT,
  DEPTH, COLORS,
} from '../config';


import { HELP_CONTROLS } from '../config/helpControls';
import { promoteToClarityCamera } from '../scenes/arena/ClarityCameraRegistry';
import { ensureRoundedTexture } from './uiTextures';
import { t } from '../i18n';

// ── Layout ────────────────────────────────────────────────────────────────────
const PANEL_W = 780;
const PANEL_H = 700;
const CX      = GAME_WIDTH  / 2;
const CY      = GAME_HEIGHT / 2;

const TITLE_Y     = CY - PANEL_H / 2 + 94;
const SEP_Y       = TITLE_Y + 32;
const LIST_START_Y = SEP_Y + 36;
const ROW_H       = 46;
const KEY_X       = CX - PANEL_W / 2 + 94;
const DESC_X      = CX - PANEL_W / 2 + 294;
const FOOTER_Y    = CY + PANEL_H / 2 - 90;

// ── Farben ────────────────────────────────────────────────────────────────────
const DIM_COLOR   = COLORS.GREY_10;
const DIM_ALPHA = 0.58;
const PANEL_BG    = SURFACE.modal;
const PANEL_BORDER = BORDER.default;

const KEY_STYLE = textStyle('label', { color: TEXT.secondary });

const DESC_STYLE = textStyle('body', { color: TEXT.primary });

export class HelpOverlay {
  private container: Phaser.GameObjects.Container | null = null;
  private dimRect:   Phaser.GameObjects.Rectangle | null = null;
  private visible = false;

  private dismissDelay: Phaser.Time.TimerEvent | null = null;
  private keyHandler:   ((e: KeyboardEvent) => void) | null = null;
  private visibilityTween: Phaser.Tweens.Tween | null = null;

  constructor(private scene: Phaser.Scene) {}

  // ── Lifecycle ─────────────────────────────────────────────────────────────

  build(): void {
    this.destroy();

    const objects: Phaser.GameObjects.GameObject[] = [];

    // ── Dunkler Fullscreen-Layer ──────────────────────────────────────────
    this.dimRect = this.scene.add.rectangle(CX, CY, GAME_WIDTH, GAME_HEIGHT, DIM_COLOR, DIM_ALPHA)
      .setScrollFactor(0);
    objects.push(this.dimRect);

    // ── Panel ─────────────────────────────────────────────────────────────
    const panel = this.scene.add.image(
      CX, CY,
      ensureModalPanelTexture(this.scene, '_help_panel', PANEL_W, PANEL_H, PANEL_BG, PANEL_BORDER),
    ).setScrollFactor(0);
    objects.push(panel);

    // ── Titel ─────────────────────────────────────────────────────────────
    objects.push(
      this.scene.add.text(CX, TITLE_Y, t('ui.help.heading'), textStyle('display'))
        .setOrigin(0.5).setScrollFactor(0),
    );

    // ── Trennlinie ────────────────────────────────────────────────────────
    objects.push(
      this.scene.add.rectangle(CX, SEP_Y, PANEL_W - 132, 1, BORDER.subtle, 0.9)
        .setScrollFactor(0),
    );

    // ── Steuerungs-Einträge ───────────────────────────────────────────────
    HELP_CONTROLS.forEach((entry, i) => {
      const y = LIST_START_Y + i * ROW_H;

      // Ruhige, gleichmaessige Zeilenflaechen statt eines starken Zebra-Musters.
      objects.push(
        this.scene.add.rectangle(CX, y, PANEL_W - 132, ROW_H - 4, SURFACE.raised, i % 2 === 0 ? 0.28 : 0.16)
          .setScrollFactor(0),
      );

      objects.push(this.scene.add.image(KEY_X + 78, y, ensureRoundedTexture(this.scene, {
        key: '_forest_help_keycap', w: 174, h: 34, radius: 7, topColor: SURFACE.raised,
        bottomColor: SURFACE.sunken, fillAlpha: .9, strokeColor: BORDER.subtle, strokeAlpha: .8, strokeWidth: 1, highlightAlpha: .04,
      })).setScrollFactor(0));
      objects.push(
        this.scene.add.text(KEY_X, y, t(entry.keyId), KEY_STYLE)
          .setOrigin(0, 0.5).setScrollFactor(0),
      );
      objects.push(
        this.scene.add.text(DESC_X, y, t(entry.descriptionKey), DESC_STYLE)
          .setOrigin(0, 0.5).setScrollFactor(0),
      );
    });

    // ── Footer-Hinweis ────────────────────────────────────────────────────
    objects.push(
      this.scene.add.text(CX, FOOTER_Y, t('ui.help.closeHint'), textStyle('caption'))
        .setOrigin(0.5).setScrollFactor(0),
    );

    // ── Container ─────────────────────────────────────────────────────────
    this.container = this.scene.add.container(0, 0, objects)
      .setDepth(DEPTH.OVERLAY + 1);
    this.container.setVisible(false);
    mountForestModal(this.scene, this.container, PANEL_W, PANEL_H);
    promoteToClarityCamera(this.scene, this.container);
  }

  show(): void {
    if (this.visible || !this.container) return;
    this.visible = true;

    // Sofort sichtbar mit Eingangsanimation
    this.container.setVisible(true);
    this.container.setAlpha(0);
    this.visibilityTween?.remove();
    this.visibilityTween = this.scene.tweens.add({
      targets: this.container,
      alpha: 1,
      duration: 150,
      ease: 'Sine.easeOut',
    });

    // Dismiss-Listener verzögert registrieren, damit der öffnende Klick
    // das Overlay nicht sofort wieder schließt.
    this.dismissDelay = this.scene.time.delayedCall(120, () => {
      this.dismissDelay = null;
      if (!this.visible) return;

      // Klick irgendwo → schließen
      this.dimRect?.setInteractive().once('pointerdown', () => this.hide());

      // Beliebige Taste → schließen
      this.keyHandler = () => this.hide();
      this.scene.input.keyboard?.on('keydown', this.keyHandler);
    });
  }

  hide(): void {
    if (!this.visible || !this.container) return;
    this.visible = false;

    // Aufräumen
    this.dismissDelay?.destroy();
    this.dismissDelay = null;
    this.dimRect?.disableInteractive().removeAllListeners();
    if (this.keyHandler) {
      this.scene.input.keyboard?.off('keydown', this.keyHandler);
      this.keyHandler = null;
    }

    // Ausgangsanimation
    this.visibilityTween?.remove();
    this.visibilityTween = this.scene.tweens.add({
      targets: this.container,
      alpha: 0,
      duration: 100,
      ease: 'Sine.easeIn',
      onComplete: () => { this.container?.setVisible(false); },
    });
  }

  isOpen(): boolean {
    return this.visible;
  }

  destroy(): void {
    this.visible = false;
    this.visibilityTween?.remove();
    this.visibilityTween = null;
    this.dismissDelay?.destroy();
    this.dismissDelay = null;
    if (this.keyHandler) {
      this.scene.input.keyboard?.off('keydown', this.keyHandler);
      this.keyHandler = null;
    }
    this.container?.destroy(true);
    this.container = null;
    this.dimRect = null;
  }
}
